mapper.select:
select o.orders_id, o.products_user_id, o.create_time, o.shipping_time, o.complete_time,
       o.total_price, o.name, o.phone, o.address, o.status, o.user_id,
       u.user_name, -- 下单用户
       (select real_name from farmers where user_id = o.products_user_id) as farmersName -- 农户名称
from orders o
left join sys_user u on o.user_id = u.user_id

     and o.orders_id = #{ordersId}
     and o.products_user_id = #{productsUserId}
     and o.status = #{status}
     and o.user_id = #{userId}

order by o.create_time desc

select orders_id, products_user_id, create_time, shipping_time, complete_time, total_price, name, phone, address, status, user_id
from orders
where orders_id = #{ordersId}

select op_id, orders_id, products_id, products_name, image, specs, origin, price, quantity
from orders_products
where orders_id = #{orders_id}

mapper.update:
update orders
products_user_id = #{productsUserId}, create_time = #{createTime}, shipping_time = #{shippingTime}, complete_time = #{completeTime}, total_price = #{totalPrice}, name = #{name}, phone = #{phone}, address = #{address}, status = #{status}, user_id = #{userId},
where orders_id = #{ordersId}
